
PRAGMA foreign_keys=ON;
CREATE TABLE microgrid(microgrid_id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL,timezone TEXT NOT NULL,nominal_frequency_hz REAL NOT NULL CHECK(nominal_frequency_hz>0),nominal_voltage_ll_v REAL NOT NULL CHECK(nominal_voltage_ll_v>0),interval_minutes INTEGER NOT NULL CHECK(interval_minutes>0));
CREATE TABLE bus(bus_id TEXT PRIMARY KEY,microgrid_id TEXT NOT NULL REFERENCES microgrid(microgrid_id),bus_name TEXT NOT NULL,nominal_voltage_ll_v REAL NOT NULL CHECK(nominal_voltage_ll_v>0),phases TEXT NOT NULL CHECK(phases IN ('ABC','AB','A','B','C')));
CREATE TABLE asset(asset_id TEXT PRIMARY KEY,microgrid_id TEXT NOT NULL REFERENCES microgrid(microgrid_id),bus_id TEXT NOT NULL REFERENCES bus(bus_id),asset_name TEXT NOT NULL,asset_type TEXT NOT NULL CHECK(asset_type IN ('grid_intertie','solar_pv','battery','load')),rated_active_power_kw REAL NOT NULL CHECK(rated_active_power_kw>=0),rated_reactive_power_kvar REAL NOT NULL CHECK(rated_reactive_power_kvar>=0),description TEXT NOT NULL);
CREATE TABLE measurement_type(measurement_type_id TEXT PRIMARY KEY,display_name TEXT NOT NULL,unit TEXT NOT NULL,semantic_definition TEXT NOT NULL);
CREATE TABLE measurement(measurement_id INTEGER PRIMARY KEY,interval_start TEXT NOT NULL,asset_id TEXT NOT NULL REFERENCES asset(asset_id),measurement_type_id TEXT NOT NULL REFERENCES measurement_type(measurement_type_id),channel TEXT NOT NULL,value REAL,source_version TEXT NOT NULL,UNIQUE(interval_start,asset_id,measurement_type_id,channel),CHECK(value IS NULL OR abs(value)<1e9));
CREATE INDEX idx_measurement_time ON measurement(interval_start);
CREATE INDEX idx_measurement_asset_time ON measurement(asset_id,interval_start);
CREATE TABLE weather(interval_start TEXT PRIMARY KEY,irradiance_w_m2 REAL NOT NULL CHECK(irradiance_w_m2>=0),ambient_temperature_c REAL NOT NULL,cloud_factor REAL NOT NULL CHECK(cloud_factor BETWEEN 0 AND 1));
CREATE TABLE battery_state(interval_start TEXT PRIMARY KEY,asset_id TEXT NOT NULL REFERENCES asset(asset_id),soc_start_pct REAL NOT NULL CHECK(soc_start_pct BETWEEN 0 AND 100),soc_end_pct REAL NOT NULL CHECK(soc_end_pct BETWEEN 0 AND 100),battery_bus_injection_kw REAL NOT NULL,capacity_kwh REAL NOT NULL CHECK(capacity_kwh>0));
CREATE TABLE dispatch(interval_start TEXT PRIMARY KEY,battery_asset_id TEXT NOT NULL REFERENCES asset(asset_id),charge_power_kw REAL NOT NULL CHECK(charge_power_kw>=0),discharge_power_kw REAL NOT NULL CHECK(discharge_power_kw>=0),dispatch_reason TEXT NOT NULL,CHECK(charge_power_kw=0 OR discharge_power_kw=0));
CREATE TABLE interval_summary(interval_start TEXT PRIMARY KEY,pv_generation_kw REAL NOT NULL,total_load_kw REAL NOT NULL,battery_bus_injection_kw REAL NOT NULL,grid_import_kw REAL NOT NULL,reactive_balance_residual_kvar REAL NOT NULL,bus_voltage_ll_v REAL NOT NULL,frequency_hz REAL NOT NULL);
